-- challenge chal_quiz_devf_211 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_devf_211', (SELECT id FROM catalog.course WHERE public_id = 'devops-foundations-ci-containers'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'devops-foundations-ci-containers') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-devf-2-1' AND is_deleted = false LIMIT 1), 'layer-cache-and-image-size-quiz', 'Which layers rebuild, and what really makes an image smaller', 'Read a Dockerfile the way the build cache does, then pick the changes that really keep build tools, old files and stale package lists out of the final image.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_devf_211');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_devf_211');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_devf_211'), 'The api image is built from this Dockerfile (line numbers added), and .dockerignore contains two lines: .git and *.md.

1  FROM python:3.13-slim
2  WORKDIR /app
3  RUN apt-get update && apt-get install -y --no-install-recommends libpq5 && rm -rf /var/lib/apt/lists/*
4  COPY requirements.txt .
5  RUN pip install --no-cache-dir -r requirements.txt
6  COPY . .
7  RUN python -m compileall -q app
8  CMD ["python", "-m", "app"]

The image was just built. A developer edits app/routes.py and README.md and runs the same docker build again on the same machine. Which numbered steps execute again instead of coming from the cache? (Step 8 only writes image metadata; leave it out.)', 'single_choice'::question_type, 'Steps 1 to 5 have the same instruction text as last time, and the only file they copy (requirements.txt in step 4) has the same content, so their cache keys are unchanged and they are reused. README.md matches *.md in .dockerignore, so it is not in the build context at all and cannot change anything. app/routes.py is in the context and step 6 (COPY . .) copies it, so the checksum of the copied files changes and step 6 misses the cache. A miss invalidates every later step, so step 7 runs again as well: steps 6 and 7. Only step 6 forgets that a miss carries down to the following steps. Steps 4 to 7 would be right if requirements.txt had changed, or if the Dockerfile copied everything before pip install. Step 3 is not re-run just because it contains apt-get update: the cache only compares the instruction text and its parent, which is exactly why update and install belong in the same RUN. None is wrong because ignoring README.md does not hide the change to app/routes.py.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_devf_211') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('Only step 6 (COPY . .)', false),
        ('Steps 6 and 7', true),
        ('Steps 4 to 7', false),
        ('Steps 3 to 7: apt-get update must fetch fresh package lists, so step 3 never comes from the cache', false),
        ('None: README.md is in .dockerignore, so the build context did not change', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_devf_211'), 'The api image is 1.1 GB and the team wants it smaller and its builds more predictable. Which statements are true? (Select all that apply.)', 'multiple_choice'::question_type, 'True: in a multi-stage build, only what you COPY --from=build into the final stage ends up there; the compiler and headers installed in the build stage stay behind. True: .dockerignore removes files from the build context, so COPY . . cannot copy them and a change to them never invalidates a layer. True: when apt-get update sits in its own RUN, that layer can be reused from the cache weeks later while a new install line asks for packages from those stale lists; one RUN with update, install and rm -rf /var/lib/apt/lists/* avoids that and keeps the lists out of the image. False: layers only add. A later RUN rm -rf /root/.cache hides the folder in the new layer, but the 300 MB still sit in the earlier layer and are still downloaded with the image; delete files in the same RUN that created them (or use pip --no-cache-dir). False: tags like python:3.13-slim are moved to new images whenever the base is rebuilt (for example with security fixes), so two builds a week apart can start from different bases; pin a digest (FROM python:3.13-slim@sha256:...) when you need the exact same base, and update the pin on purpose.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_devf_211') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('In a multi-stage build, compilers installed in the build stage are not in the final image unless a COPY --from=build copies them there', true),
        ('.dockerignore keeps files out of the build context, so COPY . . cannot copy them and changes to them do not invalidate any layer', true),
        ('Running apt-get update and apt-get install in the same RUN stops a cached, outdated apt-get update layer from being reused with a new install line', true),
        ('After one RUN downloads 300 MB into /root/.cache, adding RUN rm -rf /root/.cache as the next step makes the image 300 MB smaller', false),
        ('The tag python:3.13-slim always points to the same image, so pinning the base image by digest adds nothing', false)
    ) AS o(option_text, is_correct);

-- challenge chal_fix_devf_212 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_fix_devf_212', (SELECT id FROM catalog.course WHERE public_id = 'devops-foundations-ci-containers'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'devops-foundations-ci-containers') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-devf-2-1' AND is_deleted = false LIMIT 1), 'fix-docker-layer-cache-plan', 'Fix the build plan that promises cached layers it cannot reuse', 'Rice Rocket''s CI prints a build plan before every image build: which Dockerfile steps the layer cache will reuse (CACHED) and which ones will run again (BUILD), and how many seconds the build will take. The plan is wrong in three ways: a step that runs again does not make the steps after it run again, a COPY step only looks at the names of the files it copies and not at their content, and files listed in .dockerignore still count as part of the build context. Fix build_report(previous, current, dockerignore, seconds) so that every cache key includes its parent step''s key, the content hash of every copied file, and only the files that really reach the build. The runner at the bottom (do not change it) prints the plan as JSON.', 'open', 'medium'::difficulty_question, 'fix_bug', 20, true, false)
