-- challenge chal_quiz_devf_231 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_devf_231', (SELECT id FROM catalog.course WHERE public_id = 'devops-foundations-ci-containers'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'devops-foundations-ci-containers') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-devf-2-3' AND is_deleted = false LIMIT 1), 'what-is-inside-the-image-quiz', 'What is really inside this image?', 'Two pieces of evidence from Rice Rocket''s images: a Dockerfile that deletes a .env file, and an SBOM checked against a security advisory. Decide whether each statement follows from the evidence.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_devf_231');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_devf_231');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_devf_231'), 'The api image v2.9.0 was built from this Dockerfile. The project folder contained a .env file with DB_PASSWORD=Pr0d-Rice-2026, and there is no .dockerignore:

FROM python:3.13-slim
WORKDIR /app
COPY . .
RUN pip install --no-cache-dir -r requirements.txt
RUN rm -f /app/.env
CMD ["python", "-m", "api"]

$ docker run --rm ghcr.io/ricerocket/api:v2.9.0 ls -a /app
.  ..  Dockerfile  api  requirements.txt

Statement: "Even though ls shows no .env in the running container, anyone who pulls api:v2.9.0 can still get the password out of the image."', 'single_choice'::question_type, 'True. Layers only add. COPY . . created a layer that contains /app/.env with the password. RUN rm -f /app/.env created a new layer that only records "this path is deleted" (a whiteout), so the container''s merged view no longer shows the file - but the COPY layer is unchanged and ships with the image. docker save, or any tool that unpacks layers one by one, gets the file back in seconds; a secret scanner that reads every layer reports it. The misconception is that what a container can see is what the image contains. The fixes: keep .env out of the build context with .dockerignore, use a build secret mount for build-time secrets, and rotate the password, because the image has already been pulled.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_devf_231') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_devf_231'), 'A security advisory covers PyYAML versions before 5.4. The dispatch service''s requirements.txt pins PyYAML==6.0.2. A scanner generated a CycloneDX SBOM from the image ghcr.io/ricerocket/dispatch:v4.1.0; these are all its PyYAML entries (shortened to name, version and where the package was found):

name     version   purl                     found in
pyyaml   6.0.2     pkg:pypi/pyyaml@6.0.2    /app/.venv/lib/python3.13/site-packages/PyYAML-6.0.2.dist-info

Part of docker history for the same image:

COPY build/route-report /usr/local/bin/route-report    18.2MB

route-report is a single-file executable that the team builds with PyInstaller from a script whose own requirements pin PyYAML==5.3.1.

Statement: "Because the SBOM lists only PyYAML 6.0.2, the dispatch image v4.1.0 contains no PyYAML version that the advisory covers."', 'single_choice'::question_type, 'False. An SBOM lists what the scanner could recognise, mostly from package metadata such as the .dist-info folders pip writes. PyInstaller packs the script, the Python runtime and its libraries (here PyYAML 5.3.1) into one executable, without those folders on the image''s filesystem, so a scanner may not list them at all. The image still ships the old PyYAML inside /usr/local/bin/route-report. An entry missing from an SBOM is not proof that the package is absent: check how binaries copied in with COPY were built, generate an SBOM for them when you build them, or rebuild the tool with a fixed PyYAML. The misconception is that the SBOM is a complete inventory by definition.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_devf_231') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_devf_232 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_devf_232', (SELECT id FROM catalog.course WHERE public_id = 'devops-foundations-ci-containers'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'devops-foundations-ci-containers') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-devf-2-3' AND is_deleted = false LIMIT 1), 'scan-image-layers-for-secrets', 'Find the secrets that every layer still carries', 'Rice Rocket''s api image v2.9.0 copied a .env file with the production database password and deleted it in the next step, so docker run ... ls shows nothing - but the file is still inside the earlier layer. Write scan_image(layers), the secret scanner the CI will run on every image before it is pushed. It gets the layers in build order, each with the files it adds (path -> text, or null for a binary file) and the paths it deletes. Check every line of every text file in every layer against the three rules in the starter (an AWS access key id, a private key header, and a NAME=value line whose name contains SECRET, PASSWORD or TOKEN with a real value, not empty and not a $reference). For each finding, report the 1-based layer, the path, the line number, the rule, and in_final_image: false when a later layer deleted that path (or a directory above it) or replaced it with a newer file. Return {"findings": [...], "total": n, "hidden": number not in the final image}, ordered by layer, path, line and rule. The exact rules and an example are in the docstring of scanner.py; the runner at the bottom (do not change it) reads {"layers": [...]} from stdin and prints the result as JSON. Never print the secret itself.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
