INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_devf_232'), 1, 'Which question does the scanner answer: "what can a running container see?" or "what bytes does anyone who pulls the image get?" Which layers, and which files, does the second question include?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_devf_232'), 2, 'Split the work into three small functions, as the starter does: rules_for_line(line) looks at one line only; in_final_image(path, index, layers) only looks at the layers after index (their files and their deleted paths, with inside() for directories); scan_image loops over layers, sorted paths and str.splitlines() lines and builds the findings.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_devf_232'), 3, 'A similar case on different data: layers [{"files": {"etc/app.conf": "MAIL_TOKEN=abc"}}, {"deleted": ["etc/"]}]. ASSIGNMENT.fullmatch("MAIL_TOKEN=abc") gives the groups "MAIL_TOKEN" and "abc"; "TOKEN" is in the name and "abc" is a real value, so the line matches secret-assignment. inside("etc/app.conf", "etc/") is True, so the finding is {"layer": 1, "path": "etc/app.conf", "line": 1, "rule": "secret-assignment", "in_final_image": false}, and hidden is 1.');
