VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_devf_232'), 'The incident: .env copied in layer 2 and removed in layer 3 is still found', '{"layers":[{"created_by":"FROM python:3.13-slim","files":{"usr/local/bin/python3":null,"etc/os-release":"PRETTY_NAME=\"Debian GNU/Linux 12 (bookworm)\"\nID=debian\n"},"deleted":[]},{"created_by":"COPY . /app","files":{"app/api/main.py":"import os\nDB_URL = os.environ[''DATABASE_URL'']\n","app/.env":"DEBUG=0\nDB_PASSWORD=Pr0d-Rice-2026\nAWS_ACCESS_KEY_ID=AKIAIOSFODNN7EXAMPLE\n","app/static/logo.png":null},"deleted":[]},{"created_by":"RUN rm -f /app/.env","files":{},"deleted":["app/.env"]}]}', '{"findings":[{"layer":2,"path":"app/.env","line":2,"rule":"secret-assignment","in_final_image":false},{"layer":2,"path":"app/.env","line":3,"rule":"aws-access-key-id","in_final_image":false}],"total":2,"hidden":2}', 4, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_devf_232'), 'Clean image: references, empty values and comments are not secrets', '{"layers":[{"created_by":"FROM python:3.13-slim","files":{"usr/local/bin/python3":null,"etc/os-release":"PRETTY_NAME=\"Debian GNU/Linux 12 (bookworm)\"\nID=debian\n"},"deleted":[]},{"created_by":"COPY deploy/app.env /app/app.env","files":{"app/app.env":"DEBUG=0\nDB_PASSWORD=\"${DB_PASSWORD}\"\nexport API_TOKEN=\"\"\nSECRET_KEY_FILE=$SECRETS_DIR/key\n# DB_PASSWORD=changeme in local dev only\nLOG_LEVEL=info\n"},"deleted":[]},{"created_by":"RUN pip install -r requirements.txt","files":{"app/.venv/bin/uvicorn":null},"deleted":[]}]}', '{"findings":[],"total":0,"hidden":0}', 4, true, false, 2),
