-- challenge chal_quiz_devf_311 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_devf_311', (SELECT id FROM catalog.course WHERE public_id = 'devops-foundations-ci-containers'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'devops-foundations-ci-containers') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-devf-3-1' AND is_deleted = false LIMIT 1), 'ci-needs-if-cache-quiz', 'needs, if: and caches in a GitHub Actions workflow', 'Read two workflow snippets the way the runner does: which jobs run after a failure, and what a cache key really restores and saves.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_devf_311');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_devf_311');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_devf_311'), 'A push runs this workflow. The step in the test job exits with code 1. Which jobs run?

jobs:
  test:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - run: pytest
  build:
    needs: test
    runs-on: ubuntu-latest
    steps:
      - run: docker build -t api .
  deploy:
    needs: build
    if: always()
    runs-on: ubuntu-latest
    steps:
      - run: ./deploy.sh', 'single_choice'::question_type, 'build has no if:, so it gets the default if: success(): it only runs when every job in its needs succeeded. test failed, so build is skipped. deploy has if: always(), which replaces that default check: always() is true whatever happened to the jobs it needs (failed, skipped or even cancelled), so deploy runs although nothing was built or tested - the same mistake as in the incident. "Only test runs" would be right without the if: always() line. "build and deploy both run" ignores that needs + the default success() skip build. A failing job does not cancel the whole run by itself: jobs that do not depend on it keep running (fail-fast only cancels the other jobs of the same matrix). And deploy is not skipped "because build was skipped": with always() the status of build no longer matters.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_devf_311') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('Only test runs; build and deploy are skipped.', false),
        ('test fails, build is skipped, and deploy runs.', true),
        ('test fails, then build and deploy both run.', false),
        ('GitHub cancels the whole run as soon as test fails, so nothing else runs.', false),
        ('test fails, build is skipped, and deploy is skipped because build did not run.', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_devf_311'), 'The test job restores pip''s cache like this. Which statements are true? (Select all that apply.)

- uses: actions/cache@v4
  id: deps
  with:
    path: ~/.cache/pip
    key: deps-${{ runner.os }}-${{ hashFiles(''requirements.txt'') }}
    restore-keys: |
      deps-${{ runner.os }}-
- run: pip install -r requirements.txt', 'multiple_choice'::question_type, 'hashFiles() returns a SHA-256 hash of the file contents, so the key only changes when requirements.txt changes - not on every commit. When it changes, the exact key misses; restore-keys then restores the most recent cache whose key starts with deps-Linux-, pip install downloads only what is new, and the post step saves a new cache under the new exact key. Caches are immutable: a key that already exists is never overwritten, which is why the key must contain a hash of what you depend on. A cache is a best-effort speed-up that GitHub may evict (unused for 7 days, or over the repository''s size limit), so it is the wrong way to hand the tested image or wheel to the deploy job - that is what artifacts (or a registry with an immutable tag) are for. Because pip install still runs on every job, a restored cache can only make it faster, never leave stale packages behind; the incident happened because the install step was skipped on a cache hit with a key that never changed.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_devf_311') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('The key stays the same from commit to commit as long as the contents of requirements.txt do not change.', true),
        ('After requirements.txt changes, the exact key misses, an older cache is restored through restore-keys, and the job saves a new cache under the new key.', true),
        ('If a cache with the same key already exists, the end of the job overwrites it with the newer files.', false),
        ('The cache is a good way to pass the built wheel from the build job to the deploy job, because it is shared by every job of the repository.', false),
        ('Because pip install runs on every job, a restored older cache cannot leave the job with outdated packages.', true)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_devf_312 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_devf_312', (SELECT id FROM catalog.course WHERE public_id = 'devops-foundations-ci-containers'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'devops-foundations-ci-containers') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-devf-3-1' AND is_deleted = false LIMIT 1), 'plan-ci-job-graph', 'Plan a CI run from the needs graph', 'Rice Rocket''s workflow got slow and nobody knew which job to speed up. Write plan_run(jobs): check the needs graph (unknown needs and cycles are errors), then compute when every job starts and ends with unlimited runners, skip every job that depends on a failed or skipped job, and report the total wall time and the critical path - the chain of jobs that decided it. The runner reads the jobs from stdin and prints the plan as JSON.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
