INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_devf_321', (SELECT id FROM catalog.course WHERE public_id = 'devops-foundations-ci-containers'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'devops-foundations-ci-containers') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-devf-3-2' AND is_deleted = false LIMIT 1), 'plan-release-semver-changelog', 'Pick the latest tag, the next version and the changelog', 'Rice Rocket''s release script sorted tags as text and deployed v1.9.0 after v1.10.0, and a removed API field went out as a patch. Write plan_release(tags, commits): sort the version tags by SemVer precedence (pre-releases included, invalid tags ignored), find the latest stable release, decide the bump from Conventional Commits (a ! or a BREAKING CHANGE footer is major, feat is minor, fix and perf are patch), compute the next version and group the commits into a changelog. The runner reads the tags and commits from stdin and prints the plan as JSON.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
