VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_devf_321'), 'Example: v1.10.0 is newer than v1.9.0, a feature makes a minor release', '{"tags":["v1.9.0","v1.10.0","v1.2.3"],"commits":["feat(menu): show spicy level","fix: round VAT"]}', '{"sorted":["v1.2.3","v1.9.0","v1.10.0"],"latest":"v1.10.0","bump":"minor","next":"v1.11.0","changelog":{"Features":["menu: show spicy level"],"Fixes":["round VAT"]}}', 5, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_devf_321'), 'Pre-releases sort below their release, rc.10 after rc.2, and an rc is never the latest', '{"tags":["v2.0.0-rc.10","v2.1.0-rc.1","v1.10.0","v2.0.0","v2.0.0-rc.2","v2.0.0-beta","v2.0.0-alpha.1"],"commits":["fix(checkout): retry the payment callback once","docs: explain the refund flow","perf(dispatch): cache the driver lookup"]}', '{"sorted":["v1.10.0","v2.0.0-alpha.1","v2.0.0-beta","v2.0.0-rc.2","v2.0.0-rc.10","v2.0.0","v2.1.0-rc.1"],"latest":"v2.0.0","bump":"patch","next":"v2.0.1","changelog":{"Fixes":["checkout: retry the payment callback once","dispatch: cache the driver lookup"]}}', 5, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_devf_321'), 'A BREAKING CHANGE footer makes a major release, whatever the commit type', '{"tags":["v1.4.2","v1.4.1","v1.3.0"],"commits":["feat(orders): add a pickup time to orders","refactor(api): rename orders.total to orders.total_vnd\n\nThe mobile app must read the new field.\n\nBREAKING CHANGE: orders.total is removed from the API response","fix: show the right currency symbol","chore(ci): pin actions to commit SHAs"]}', '{"sorted":["v1.3.0","v1.4.1","v1.4.2"],"latest":"v1.4.2","bump":"major","next":"v2.0.0","changelog":{"Breaking changes":["api: rename orders.total to orders.total_vnd"],"Features":["orders: add a pickup time to orders"],"Fixes":["show the right currency symbol"]}}', 5, true, false, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_devf_321'), 'Invalid tags are ignored; chores and docs alone need no release', '{"tags":["latest","v1.2","release-2026-10","v01.2.3","1.4.0","v1.4.0+build.7","v1.3.9","v1.4.0-rc.1"],"commits":["chore: bump pre-commit hooks","docs(readme): add the on-call phone list","Merge branch ''main'' into feature/refunds"]}', '{"sorted":["v1.3.9","v1.4.0-rc.1","1.4.0","v1.4.0+build.7"],"latest":"v1.4.0+build.7","bump":null,"next":null,"changelog":{}}', 5, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_devf_321'), 'No tags yet: base v0.0.0; Feat(api)! is breaking; other formats are ignored', '{"tags":[],"commits":["Initial commit","Feat(api)!: return prices in VND as integers","feat: add the dispatch worker","fix typo in README","fix(api): handle an empty cart"]}', '{"sorted":[],"latest":null,"bump":"major","next":"v1.0.0","changelog":{"Breaking changes":["api: return prices in VND as integers"],"Features":["add the dispatch worker"],"Fixes":["api: handle an empty cart"]}}', 5, false, true, 5),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_devf_321'), 'The full pre-release ladder, and build metadata keeps input order', '{"tags":["1.0.0","1.0.0-rc.1","v1.0.0-beta.11","1.0.0-beta.2","1.0.0-beta","1.0.0-alpha.beta","1.0.0-alpha.1","1.0.0-alpha","v1.0.0+linux","0.9.12"],"commits":["feat(menu): filter by district","feat(menu)!: drop the old price field\n\nBREAKING-CHANGE: clients must use price_vnd","fix: menu images on slow networks"]}', '{"sorted":["0.9.12","1.0.0-alpha","1.0.0-alpha.1","1.0.0-alpha.beta","1.0.0-beta","1.0.0-beta.2","v1.0.0-beta.11","1.0.0-rc.1","1.0.0","v1.0.0+linux"],"latest":"v1.0.0+linux","bump":"major","next":"v2.0.0","changelog":{"Breaking changes":["menu: drop the old price field"],"Features":["menu: filter by district"],"Fixes":["menu images on slow networks"]}}', 5, false, true, 6);
