-- challenge chal_quiz_devf_331 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_devf_331', (SELECT id FROM catalog.course WHERE public_id = 'devops-foundations-ci-containers'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'devops-foundations-ci-containers') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-devf-3-3' AND is_deleted = false LIMIT 1), 'rollback-ready-releases-quiz', 'Can you roll this release back?', 'Two decisions from the checkout incident: which image reference lets you redeploy exactly what ran yesterday, and which migration plan keeps the previous version working while both versions share one database.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_devf_331');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_devf_331');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_devf_331'), 'Rice Rocket''s checkout v2.13.4 ran fine yesterday. Today v2.14.0 is broken and you want to redeploy exactly the image bytes that ran yesterday. Which of these image references are guaranteed to give you yesterday''s image? (Select all that apply.)', 'multiple_choice'::question_type, 'A digest (image@sha256:...) is the hash of the image manifest itself, so it can only ever point to those exact bytes. A version tag such as v2.13.4 is safe when the registry enforces tag immutability (Amazon ECR and other registries can reject a push that would overwrite an existing tag), because then nobody can move it. latest is moved by every push from main, so today it points to v2.14.0 - that is what made the incident''s rollback take 40 minutes. A tag named after the git commit is a good convention, but without immutability a re-run of the pipeline (or anyone with push rights) can push different bytes under the same name, so it is not guaranteed. kubectl rollout undo goes back to the previous pod template; if that template also says checkout:latest, it starts the same new image again.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_devf_331') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('ricerocket/checkout@sha256:9f2c... (the digest recorded by yesterday''s deploy)', true),
        ('ricerocket/checkout:v2.13.4 in a registry that has tag immutability turned on', true),
        ('ricerocket/checkout:latest with imagePullPolicy: Always', false),
        ('ricerocket/checkout:3f9a1c2 (the git commit) in a registry where tags can be overwritten', false),
        ('Whatever kubectl rollout undo deployment/checkout picks, when the Deployment uses checkout:latest', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_devf_331'), 'v3.8.0 of the dispatch service stores each rider''s vehicle plate in a new column riders.plate_number instead of riders.vehicle_no. During a rolling deploy old (v3.7) and new pods run side by side against one Postgres database, and v3.7 must stay a working rollback target for a few days. Which plan is safe?', 'single_choice'::question_type, 'Expand and contract: first expand the schema in a way both versions accept (add plate_number, write both columns, backfill old rows), then switch reads to the new column in a later release, and only contract (drop vehicle_no) once no running or rollback-target version reads it. Every step is backward compatible, so you can roll back the code at any point. RENAME COLUMN in the same release breaks every v3.7 pod the moment the migration runs, and makes v3.7 useless as a rollback target - the same failure as the checkout incident in this lesson. Deploying the code first means the new pods query a column that does not exist yet. A blue-green copy of the database splits the data: riders registered or updated in blue after the copy are missing in green. Restoring a backup to roll back throws away every change made since the backup.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_devf_331') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('One migration in v3.8.0: ALTER TABLE riders RENAME COLUMN vehicle_no TO plate_number, applied right before the new pods start', false),
        ('v3.8.0 adds plate_number, writes both columns and backfills old rows; v3.9.0 reads only plate_number; a later release drops vehicle_no', true),
        ('Deploy v3.8.0 (reading plate_number) first and run the rename migration once all pods are on v3.8.0', false),
        ('Use blue-green: give the green environment a copy of the database with the column renamed, then switch the router', false),
        ('Drop vehicle_no in v3.8.0; if a rollback is needed, restore last night''s backup first', false)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_devf_332 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_devf_332', (SELECT id FROM catalog.course WHERE public_id = 'devops-foundations-ci-containers'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'devops-foundations-ci-containers') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-devf-3-3' AND is_deleted = false LIMIT 1), 'automated-canary-analysis', 'Let the numbers promote or roll back the canary', 'Write analyze_canary(config, steps), the gate the deploy tool runs after every canary step instead of a person eyeballing a dashboard. Check the steps in order and stop at the first one that fails: too little canary traffic means HOLD, an error rate too far above the baseline or a p95 too far above the baseline means ROLLBACK, and a release that passes every step is promoted. The runner prints the decision, the weight where the release stopped, the reason with the measured numbers, and the result of every step that was checked.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
