-- challenge chal_quiz_devf_341 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_devf_341', (SELECT id FROM catalog.course WHERE public_id = 'devops-foundations-ci-containers'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'devops-foundations-ci-containers') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-devf-3-4' AND is_deleted = false LIMIT 1), 'bad-release-evidence-quiz', 'Read the evidence of the release that said OK', 'Walk through one evidence pack from the checkout incident, step by step: the deploy log, the health-check output, the error-rate graph and the health handler, then the decision to roll back and the check of the fix. Decide for each statement whether the evidence supports it.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
