WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_devf_341'), 'Evidence 2 of 4 - at 14:09 the on-call engineer calls /health on one v3.2.0 pod, then reads that pod''s log:

$ curl -s -w '' %{http_code} %{time_total}s\n'' http://10.4.7.21:8080/health
{"status": "ok", "version": "3.2.0"} 200 0.002s

$ kubectl logs checkout-6f9c7b-x2kqp --since=1m | grep ERROR | tail -1
ERROR POST /orders 500 psycopg.OperationalError: connection to server on socket "/var/run/postgresql/.s.PGSQL.5432" failed: No such file or directory

Statement: "Because /health answered 200 in 2 ms on this pod, the pod was able to take orders at 14:09."', 'single_choice'::question_type, 'False. In the same minute the same pod failed POST /orders with a database connection error. A 200 from /health only shows that the web server process is running and can answer a request that touches nothing else. The error itself is a clue: libpq tried the default local socket /var/run/postgresql, which is what happens when the connection string is empty. A health check is only as good as what it checks.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_devf_341') AND order_index = 2)
    RETURNING id
)
