INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_fix_devf_342', (SELECT id FROM catalog.course WHERE public_id = 'devops-foundations-ci-containers'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'devops-foundations-ci-containers') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-devf-3-4' AND is_deleted = false LIMIT 1), 'fix-readiness-check', 'Fix the readiness check that still says ready too easily', 'After the incident, Rice Rocket''s checkout got a real readiness endpoint: GET /ready returns readiness(snapshot), and Kubernetes sends traffic to a pod only while it answers 200. On staging it still let broken pods through. A pod whose DATABASE_URL was set to an empty string reported ready. A pod whose database answered SELECT 1 in 2.4 seconds, with a 500 ms timeout, reported ready. And when a broken metrics exporter sent the check result ok as the string "false", the pod reported ready as well. Fix the functions in readiness.py so they follow the rules in the docstring: every problem is listed (config first, then checks in order), with the exact texts given there, and the answer is {"status": 200, "ready": true, "problems": []} or status 503 with ready false. The runner at the bottom (do not change it) reads one snapshot from stdin and prints the answer as JSON.', 'open', 'medium'::difficulty_question, 'fix_bug', 30, true, false)
