-- learners enrolled before these lessons existed
INSERT INTO learning.history (user_id, course_id, module_id, lesson_id)
SELECT r.user_id, r.course_id, m.id, l.id
FROM learning.register r
JOIN course.module m ON m.course_id = r.course_id AND m.is_deleted = false
JOIN course.lesson l ON l.module_id = m.id AND l.is_deleted = false
WHERE r.course_id = (SELECT id FROM catalog.course WHERE public_id = 'devops-foundations-ci-containers') AND r.is_deleted = false
ON CONFLICT DO NOTHING;
WITH ordered AS (
    SELECT h.user_id, h.lesson_id, h.status,
           row_number() OVER (PARTITION BY h.user_id ORDER BY m.order_index, l.order_index) AS rn
    FROM learning.history h
    JOIN course.lesson l ON l.id = h.lesson_id AND l.is_deleted = false
    JOIN course.module m ON m.id = l.module_id AND m.is_deleted = false
    WHERE h.course_id = (SELECT id FROM catalog.course WHERE public_id = 'devops-foundations-ci-containers')
),
next_lesson AS (
    SELECT DISTINCT ON (o.user_id) o.user_id, o.lesson_id
    FROM ordered o
    WHERE o.status = 'enrolled'
      AND NOT EXISTS (SELECT 1 FROM ordered p WHERE p.user_id = o.user_id AND p.rn < o.rn AND p.status <> 'completed')
    ORDER BY o.user_id, o.rn
)
UPDATE learning.history h
SET status = 'in_progress', updated_at = now()
FROM next_lesson n
JOIN learning.register r ON r.user_id = n.user_id AND r.course_id = (SELECT id FROM catalog.course WHERE public_id = 'devops-foundations-ci-containers') AND r.is_deleted = false AND r.status <> 'enrolled'
WHERE h.user_id = n.user_id AND h.course_id = (SELECT id FROM catalog.course WHERE public_id = 'devops-foundations-ci-containers') AND h.lesson_id = n.lesson_id;
UPDATE learning.register r
SET status = 'in_progress'
WHERE r.course_id = (SELECT id FROM catalog.course WHERE public_id = 'devops-foundations-ci-containers') AND r.status = 'completed'
  AND EXISTS (SELECT 1 FROM learning.history h WHERE h.user_id = r.user_id AND h.course_id = (SELECT id FROM catalog.course WHERE public_id = 'devops-foundations-ci-containers') AND h.status <> 'completed');

COMMIT;
